import networkx as nx

def get_betweenness_centrality(graph):
    return nx.betweenness_centrality(graph, normalized=False)

def calculate_capacity(load, alpha=0.2):
    return (1 + alpha) * load

def perform_cascade(graph, initial_loads):
    alpha = 0.2
    capacities = {bus: calculate_capacity(load, alpha) for bus, load in initial_loads.items()}

    while True:
        current_loads = nx.betweenness_centrality(graph, normalized=False)
        overloaded_buses = [bus for bus in graph.nodes if current_loads[bus] > capacities[bus]]

        if not overloaded_buses:
            break

        graph.remove_nodes_from(overloaded_buses)

    return len(max(nx.connected_components(graph), key=len))

# Step 1: Calculate initial loads and determine the initial maximum connected component size
initial_loads = get_betweenness_centrality(H)
initial_size = len(initial_loads)

# Step 2: Evaluate removal of each bus and determine the size of the largest component left after cascade
results = {}

for bus in H.nodes:
    temp_graph = H.copy()
    temp_graph.remove_node(bus)
    surviving_size = perform_cascade(temp_graph, {k: v for k, v in initial_loads.items() if k != bus})
    results[bus] = surviving_size

# Step 3: Determine the bus that leads to the smallest surviving connected network
smallest_survivor = min(results.items(), key=lambda x: x[1])
smallest_bus = smallest_survivor[0]
smallest_survivor_size = smallest_survivor[1]

